SELECT j.*,p.__read_size,p.__read_total,p.__read_position,p.__read_candidates FROM (SELECT *,sum(__read_size) OVER (ORDER BY loop_id,sequence) AS __read_total,row_number() OVER (ORDER BY loop_id,sequence) AS __read_position,count(*) OVER () AS __read_candidates FROM (SELECT session_id,loop_id,sequence,(COALESCE(length(CAST(session_id AS BLOB)),0)+COALESCE(length(CAST(loop_id AS BLOB)),0)+COALESCE(length(CAST(sequence AS BLOB)),0)+COALESCE(length(CAST(idempotency_key AS BLOB)),0)+COALESCE(length(CAST(command_sha256 AS BLOB)),0)+COALESCE(length(CAST(event_sha256 AS BLOB)),0)+COALESCE(length(CAST(event_json AS BLOB)),0)+COALESCE(length(CAST(created_at AS BLOB)),0)+1024) AS __read_size FROM claim_loop_events WHERE session_id=? AND (? OR loop_id>? OR (loop_id=? AND sequence>?)) ORDER BY loop_id,sequence LIMIT ?)) AS p CROSS JOIN claim_loop_events AS j WHERE (p.__read_total<=? OR p.__read_position=1) AND j.session_id=p.session_id AND j.loop_id=p.loop_id AND j.sequence=p.sequence ORDER BY p.loop_id,p.sequence